{% extends "_base.html" %}
{% load static %}
{% load i18n %}
{% load crispy_forms_tags %}
{% load crispy_forms_filters %}
{% block title %}{% trans "Upload new document" %}{% endblock title %}

{% block content %}
<style>
  :root{
    --bg:#eef8ff;
    --card:#ffffff;
    --text:#1a2433;
    --muted:#6b7a90;
    --primary:#3663ff;
    --primary-600:#2f57e6;
    --success:#12b76a;
    --radius:16px;
  }
  body{font-family:Montserrat,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
  .page-wrap{background:var(--bg); padding:28px 0 64px}
  .container-nice{max-width:1100px; margin:0 auto; padding:0 16px}
  .back-btn{display:inline-flex; align-items:center; gap:8px; padding:8px 12px; border:1px solid #d5e3ff; border-radius:10px; background:#fff; color:var(--text); text-decoration:none; font-weight:600}
  .back-btn:hover{background:#f4f7ff}
  .heading{margin:24px 0 8px; text-align:center; font-size:30px; font-weight:800; color:var(--text)}
  .subheading{margin:0 0 28px; text-align:center; color:var(--muted)}
  /* Card */
  .card{background:var(--card); border-radius:var(--radius); box-shadow:0 6px 24px rgba(32,56,117,.08); border:1px solid #e9f1ff}
  .card + .card{margin-top:18px}
  .card-h{padding:22px 26px; border-bottom:1px solid #edf3ff; font-weight:700}
  .card-b{padding:26px}

  /* Dropzone */
  .drop{border:2px dashed #d4e2ff; background:#f6fbff; border-radius:14px; display:flex; align-items:center; justify-content:center; min-height:260px; text-align:center; transition:.2s}
  .drop.dragover{background:#eef5ff; border-color:var(--primary)}
  .drop .icon{width:64px; height:64px; color:#98b2ff; margin-bottom:10px}
  .drop-title{font-weight:700; color:var(--text)}
  .drop-help{color:var(--muted); font-size:14px}
  .drop small{display:block; margin-top:6px; color:#9aa7bd}

  /* Grid form */
  .grid{display:grid; grid-template-columns:1fr 1fr; gap:18px}
  @media (max-width:900px){.grid{grid-template-columns:1fr}}
  .field label{display:block; margin:0 0 8px; color:#4b5a75; font-weight:600}
  .field input[type="text"], .field input[type="number"], .field select, .field textarea{
    width:100%; border:1px solid #dbe6ff; background:#f9fbff; border-radius:10px; padding:12px 14px; outline:0; transition:.15s; color:var(--text)
  }
  .field input:focus, .field select:focus, .field textarea:focus{border-color:var(--primary); box-shadow:0 0 0 3px rgba(54,99,255,.10)}
  .hint{font-size:12px; color:#8391a7; margin-top:6px}
  .row{display:flex; align-items:center; gap:10px}
  .switch{display:inline-flex; align-items:center; gap:10px; user-select:none}
  .switch input{width:18px; height:18px}
  .sr-only{position:absolute !important; left:-9999px !important; width:1px; height:1px; overflow:hidden}

  /* Footer actions */
  .form-actions{display:flex; justify-content:center; margin-top:18px}
  .btn-primary{background:var(--primary); color:#fff; border:0; border-radius:12px; padding:12px 18px; font-weight:700; cursor:pointer}
  .btn-primary:hover{background:var(--primary-600)}
  .errorlist{margin:8px 0 0; color:#d92d20; list-style:none; padding:0; font-size:13px}

  /* Requirements */
  .req-grid{display:grid; grid-template-columns:1fr 1fr; gap:18px}
  @media (max-width:900px){.req-grid{grid-template-columns:1fr}}
  .req h4{margin:0 0 10px; color:#1f3b57; font-weight:800}
  .req ul{margin:0; padding-left:18px; color:#4b5a75}
  .drop-preview{display:none; text-align:center}
  .file-pill{
    display:inline-flex; align-items:center; gap:10px;
    background:#eef5ff; border:1px solid #dce7ff; border-radius:999px;
    padding:8px 12px; font-weight:600; color:#1a2433;
  }
  .file-pill small{font-weight:500; color:#6b7a90}
  .pill-x{
    border:0; background:#fff; width:24px; height:24px; border-radius:50%;
    display:inline-flex; align-items:center; justify-content:center; cursor:pointer;
    box-shadow:0 0 0 1px #dce7ff inset;
  }
  .pill-x:hover{background:#f4f8ff}
  .modules-select{
    position:relative;
    width:100%;
    max-width:100%;
  }
  .modules-trigger{
    width:100%;
    display:flex;
    align-items:center;
    justify-content:space-between;
    gap:8px;
    padding:12px 14px;
    border-radius:10px;
    background:#f9fbff;
    border:1px solid #dbe6ff;
    cursor:pointer;
    font-weight:500;
    color:var(--text);
  }
  .modules-trigger span{
    overflow:hidden;
    text-overflow:ellipsis;
    white-space:nowrap;
  }
  .modules-select.open .modules-trigger{
    border-color:var(--primary);
    box-shadow:0 0 0 3px rgba(54,99,255,.10);
  }

  .modules-dropdown{
    position:absolute;
    inset-inline:0;
    margin-top:4px;
    border-radius:12px;
    background:#ffffff;
    border:1px solid #e0ebff;
    box-shadow:0 12px 30px rgba(15,23,42,.12);
    max-height:260px;
    overflow:auto;
    z-index:30;
    display:none;
  }
  .modules-select.open .modules-dropdown{
    display:block;
  }

  .modules-actions{
    position:sticky;
    top:0;
    z-index:1;
    display:flex;
    justify-content:space-between;
    align-items:center;
    padding:6px 10px;
    background:#ffffff;
    border-bottom:1px solid #eef2ff;
  }
  .modules-action{
    border:0;
    background:transparent;
    font-size:12px;
    font-weight:600;
    color:var(--primary);
    padding:4px 8px;
    border-radius:999px;
    cursor:pointer;
  }
  .modules-action:hover{
    background:#eff4ff;
  }

  .modules-list{
    padding:4px 0;
  }

  .module-item{
    display:flex;
    align-items:center;
    gap:8px;
    padding:6px 12px;
    font-size:14px;
    color:#1f2933;
    cursor:pointer;
  }
  .module-item:hover{
    background:#f3f7ff;
  }
  .module-item input[type="checkbox"]{
    flex-shrink:0;
  }
  .module-label{
    flex:1;
  }
  .modules-select.modules-error .modules-trigger{
    border-color:#d92d20;
    box-shadow:0 0 0 3px rgba(217,45,32,.15);
  }

</style>

<div class="page-wrap">
  <div class="container-nice">

    <a href="javascript:history.back()" class="back-btn">
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none"><path d="M15 18l-6-6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>
      {% trans "Back" %}
    </a>

    <h1 class="heading">{% trans "Upload new document" %}</h1>
    <p class="subheading">{% trans "Upload a document to check for originality. We support PDF, DOC, DOCX, TXT, RTF, ZIP." %}</p>
     {% if request.user.test_group %}
    <div style="display:flex;justify-content:flex-end;margin:8px 0 16px">
      <a href="{% url 'document_multi_create' %}" class="back-btn">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" style="margin-right:6px">
          <path d="M12 4v12m-6-6h12" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
        {% trans "Загрузить несколько документов" %}
      </a>
    </div>
    {% endif %}

    <form method="post" enctype="multipart/form-data" id="checkForm">
      {% csrf_token %}

      {% if form.non_field_errors %}
        <div class="card" style="border-color:#ffd8d6;background:#fff5f5">
          <div class="card-b">
            <ul class="errorlist">{{ form.non_field_errors }}</ul>
          </div>
        </div>
      {% endif %}

      <!-- Документ для проверки -->
      <div class="card">
        <div class="card-h">{% trans "Document to check" %}</div>
        <div class="card-b">
          <div id="drop" class="drop">
            <!-- приглашение (видно до выбора файла) -->
            <div id="dropInvite">
              <svg class="icon" viewBox="0 0 24 24" fill="none">
                <path d="M12 16V4m0 0l-4 4m4-4l4 4M4 16v2a2 2 0 002 2h12a2 2 0 002-2v-2"
                      stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
              <div class="drop-title">{% trans "Drag a file here or click to choose" %}</div>
              <div class="drop-help">{% trans "Supported formats" %}: PDF, DOC, DOCX, TXT, RTF</div>
              <small>{% trans "Max file size" %}: 50 MB</small>
            </div>

            <!-- превью выбранного файла (покажем после выбора/дропа) -->
            <div id="dropPreview" class="drop-preview">
              <div class="file-pill">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                  <path d="M14.5 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V7.5L14.5 2z"
                        stroke="currentColor" stroke-width="1.5"/>
                  <path d="M14 2v6h6" stroke="currentColor" stroke-width="1.5"/>
                </svg>
                <span id="fileName">file.ext</span>
                <small id="fileSize">0 KB</small>
                <button type="button" id="clearFile" class="pill-x" title="{% trans 'Remove file' %}">×</button>
              </div>
              <div class="hint" style="margin-top:6px;">
                {% trans "Click to choose another file or drag a new one here" %}
              </div>
            </div>

            <!-- сам input[type=file] (оставляем скрытым) -->
            {% if form.file %}
              <input type="file" id="realFileInput" name="{{ form.file.html_name }}" class="sr-only">
            {% elif form.document %}
              <input type="file" id="realFileInput" name="{{ form.document.html_name }}" class="sr-only">
            {% elif form.document_file %}
              <input type="file" id="realFileInput" name="{{ form.document_file.html_name }}" class="sr-only">
            {% else %}
              <input type="file" id="realFileInput" name="file" class="sr-only">
            {% endif %}
          </div>
          <!-- ошибки к файлу, если есть -->
          {% if form.file.errors %}<ul class="errorlist">{{ form.file.errors }}</ul>{% endif %}
          {% if form.document.errors %}<ul class="errorlist">{{ form.document.errors }}</ul>{% endif %}
          {% if form.document_file.errors %}<ul class="errorlist">{{ form.document_file.errors }}</ul>{% endif %}
        </div>
      </div>

      <!-- Информация о документе -->
      <div class="card">
        <div class="card-h">{% trans "Document information" %}</div>
        <div class="card-b">
          <div class="grid">
            <!-- левая колонка -->
            <div class="field">
              <label for="id_title">{% trans "Title" %}</label>
              {% if form.title %}
                {{ form.title }}
                {% if form.title.errors %}<ul class="errorlist">{{ form.title.errors }}</ul>{% endif %}
              {% else %}
                <input type="text" id="id_title" name="title" placeholder="{% trans 'Enter document title' %}">
              {% endif %}
            </div>

            <div class="field">
              <label for="id_author">{% trans "Author" %}</label>
              {% if form.author %}
                {{ form.author }}
                {% if form.author.errors %}<ul class="errorlist">{{ form.author.errors }}</ul>{% endif %}
              {% else %}
                <input type="text" id="id_author" name="author" placeholder="{% trans 'Enter author name' %}">
              {% endif %}
            </div>

            <div class="field">
              <label for="id_document_type">{% trans "Document type" %} *</label>
              {% if form.document_type %}
                {{ form.document_type }}
                {% if form.document_type.errors %}<ul class="errorlist">{{ form.document_type.errors }}</ul>{% endif %}
              {% else %}
                <select id="id_document_type" name="document_type">
                  <option value="" selected disabled>{% trans "Choose document type" %}</option>
                  <option>Article</option><option>Course work</option>
                  <option>Diploma</option><option>Thesis</option>
                </select>
              {% endif %}
            </div>

                        <div class="field">
              <label for="id_department">{% trans "Department" %}</label>
              {% if form.department %}
                {{ form.department }}
                {% if form.department.errors %}<ul class="errorlist">{{ form.department.errors }}</ul>{% endif %}
              {% else %}
                <input type="text" id="id_department" name="department" placeholder="{% trans 'Enter department' %}">
              {% endif %}
            </div>

            <!-- Модули проверки -->
            <div class="field" style="grid-column:1/-1">
              <label>{% trans "Modules for checking" %}</label>

              {% if form.modules %}
                <div class="modules-select" id="modulesSelect">
                  <button type="button" class="modules-trigger" id="modulesTrigger">
                    <span id="modulesSummary"
                          data-placeholder="{% trans 'Choose modules for checking' %}">
                      {% trans "Choose modules for checking" %}
                    </span>
                    <svg width="18" height="18" viewBox="0 0 24 24" aria-hidden="true">
                      <path d="M6 9l6 6 6-6"
                            stroke="currentColor"
                            stroke-width="2"
                            stroke-linecap="round"
                            stroke-linejoin="round"/>
                    </svg>
                  </button>

                  <div class="modules-dropdown" id="modulesDropdown">
                    <div class="modules-actions">
                      <button type="button"
                              class="modules-action"
                              data-action="select-all">
                        {% trans "Select all modules" %}
                      </button>
                      <button type="button"
                              class="modules-action"
                              data-action="clear-all">
                        {% trans "Clear selection" %}
                      </button>
                    </div>

                    <div class="modules-list">
                      {% for checkbox in form.modules %}
                        <label class="module-item">
                          {{ checkbox.tag }}
                          <span class="module-label">{{ checkbox.choice_label }}</span>
                        </label>
                      {% endfor %}
                    </div>
                  </div>

                  {% if form.modules.help_text %}
                    <div class="hint" style="margin-top:8px;">
                      {{ form.modules.help_text }}
                    </div>
                  {% endif %}

                  {% if form.modules.errors %}
                    <ul class="errorlist" style="margin-top:6px;">
                      {{ form.modules.errors }}
                    </ul>
                  {% endif %}
                  {% if form.modules.errors %}
  <ul class="errorlist" style="margin-top:6px;">
    {{ form.modules.errors }}
  </ul>
{% endif %}

<p id="modulesClientError"
   class="errorlist"
   style="margin-top:6px; display:none;">
  {% trans "Select at least one module." %}
</p>

                </div>
              {% else %}
                <p class="hint">{% trans "No modules available for selection." %}</p>
              {% endif %}
            </div>

            <div class="field">
              <div class="mb-3">
                {{ form.folder|as_crispy_field }}
              </div>



              <div class="hint">{% trans "Select an existing folder or create a new one." %}</div>
            </div>

            <!-- OCR -->
            <div class="field" style="grid-column:1/-1">
              <label>{% trans "Choose OCR" %}</label>
              <div class="row">
                <label class="switch">
                  {% if form.include_ocr %}
                    {{ form.include_ocr }}
                  {% else %}
                    <input type="checkbox" id="id_include_ocr" name="include_ocr">
                  {% endif %}
                  <span>{% trans "Enable OCR" %}</span>
                </label>
              </div>
              <div class="hint">{% trans "OCR lets you check scanned PDFs by recognizing text in images." %}</div>

              <!-- языки OCR: показываем, если есть такое поле -->
              <div id="ocrLanguagesWrap" style="{% if form.ocr_languages %}display:none{% else %}display:none{% endif %}; margin-top:10px">
                {% if form.ocr_languages %}
                  <label style="margin-top:10px">{% trans "OCR languages" %}</label>
                  {{ form.ocr_languages }}
                  {% if form.ocr_languages.errors %}<ul class="errorlist">{{ form.ocr_languages.errors }}</ul>{% endif %}
                {% endif %}
              </div>
            </div>
          </div>

          <div class="form-actions">
            <button type="submit" class="btn-primary">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" style="margin-right:6px;vertical-align:-2px">
                <path d="M4 17v2a2 2 0 002 2h12a2 2 0 002-2v-2M7 9l5-5 5 5M12 4v12" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
              {% trans "Upload document" %}
            </button>
          </div>
        </div>
      </div>

      <!-- Требования и рекомендации -->
      <div class="card">
        <div class="card-b req-grid">
          <div class="req">
            <h4>{% trans "Supported formats" %}</h4>
            <ul>
              <li>PDF</li>
              <li>Microsoft Word (DOC, DOCX)</li>
              <li>TXT</li>
              <li>RTF</li>
            </ul>
          </div>
          <div class="req">
            <h4>{% trans "Recommendations" %}</h4>
            <ul>
              <li>{% trans "Max size: 50 MB" %}</li>
              <li>{% trans "Minimum length: 1000 characters" %}</li>
              <li>{% trans "Document should contain text" %}</li>
              <li>{% trans "Avoid password-protected files" %}</li>
            </ul>
          </div>
        </div>
      </div>

    </form>
  </div>
</div>

<script>
  (function(){
    const drop          = document.getElementById('drop');
    const invite        = document.getElementById('dropInvite');
    const preview       = document.getElementById('dropPreview');
    const fileNameEl    = document.getElementById('fileName');
    const fileSizeEl    = document.getElementById('fileSize');
    const clearBtn      = document.getElementById('clearFile');
    const fileInput     = document.getElementById('realFileInput') || drop.querySelector('input[type="file"]');

    const fmtSize = bytes => {
      if (!bytes && bytes !== 0) return '';
      const units = ['B','KB','MB','GB'];
      let i = 0, v = bytes;
      while (v >= 1024 && i < units.length-1){ v /= 1024; i++; }
      return `${v.toFixed(v < 10 && i ? 1 : 0)} ${units[i]}`;
    };

    const syncTitleFromFile = (file) => {
      if (!file) return;
      const titleInput = document.getElementById('id_title');
      if (!titleInput) return;

      if (titleInput.value && titleInput.value.trim().length > 0) {
        return;
      }

      const name = file.name || '';
      const dotIndex = name.lastIndexOf('.');
      const baseName = dotIndex > 0 ? name.slice(0, dotIndex) : name;

      titleInput.value = baseName;
    };

    const showPreview = file => {
      if(!file) return resetPreview();
      fileNameEl.textContent = file.name;
      fileSizeEl.textContent = `• ${fmtSize(file.size)}`;
      invite.style.display = 'none';
      preview.style.display = 'block';

      syncTitleFromFile(file);
    };

    const resetPreview = () => {
      preview.style.display = 'none';
      invite.style.display = 'block';
    };

    const openPicker = () => fileInput && fileInput.click();
    drop.addEventListener('click', openPicker);

    // drag events
    ['dragenter','dragover'].forEach(ev => drop.addEventListener(ev, e => {
      e.preventDefault(); e.stopPropagation(); drop.classList.add('dragover');
    }));
    ['dragleave','drop'].forEach(ev => drop.addEventListener(ev, e => {
      e.preventDefault(); e.stopPropagation(); drop.classList.remove('dragover');
    }));

    // обработка drop
    drop.addEventListener('drop', e => {
      if(!fileInput) return;
      const dt = e.dataTransfer;
      if(dt && dt.files && dt.files.length){
        const f = dt.files[0];
        try { fileInput.files = dt.files; } catch(_) {}
        fileInput.dispatchEvent(new Event('change', {bubbles:true}));
        showPreview(f); 
      }
    });

    fileInput && fileInput.addEventListener('change', e => {
      const f = e.target.files && e.target.files[0];
      if (f) showPreview(f); else resetPreview();
    });

    clearBtn && clearBtn.addEventListener('click', e => {
      e.stopPropagation();
      try { fileInput.value = ''; } catch(_) {}
      resetPreview();
    });


  })();
  (function(){
  const sel = document.getElementById('id_folder');
  const input = document.getElementById('id_new_folder');
  if(!sel || !input) return;
  const toggle = () => { input.style.display = sel.value === '__new__' ? 'block' : 'none'; };
  sel.addEventListener('change', toggle);
  toggle();
})();
(function(){
    const wrapper   = document.getElementById('modulesSelect');
    if (!wrapper) return;

    const trigger      = document.getElementById('modulesTrigger');
    const dropdown     = document.getElementById('modulesDropdown');
    const summary      = document.getElementById('modulesSummary');
    const placeholder  = summary.dataset.placeholder || 'Выберите модули';
    const checkboxes   = dropdown.querySelectorAll('input[type="checkbox"]');
    const clientError  = document.getElementById('modulesClientError');
    const form         = document.getElementById('checkForm');

    const getChecked = () =>
      dropdown.querySelectorAll('input[type="checkbox"]:checked');

    const updateSummary = () => {
      const checked = getChecked();
      if (!checked.length) {
        summary.textContent = placeholder;
        return;
      }
      if (checked.length === 1) {
        const labelEl = checked[0].closest('.module-item')
                          ?.querySelector('.module-label');
        summary.textContent = labelEl
          ? labelEl.textContent.trim()
          : placeholder;
      } else {
        summary.textContent = `Выбрано модулей: ${checked.length}`;
      }
    };

    const hideClientError = () => {
      if (clientError) clientError.style.display = 'none';
      wrapper.classList.remove('modules-error');
    };

    const showClientError = () => {
      if (clientError) clientError.style.display = 'block';
      wrapper.classList.add('modules-error');
    };

    const setAll = (value) => {
      checkboxes.forEach(cb => {
        cb.checked = value;
      });
      updateSummary();
      hideClientError();
    };

    if (getChecked().length === 0) {
      setAll(true);
    } else {
      updateSummary();
    }

    trigger.addEventListener('click', function (e) {
      e.stopPropagation();
      wrapper.classList.toggle('open');
    });

    wrapper.querySelectorAll('.modules-action').forEach(btn => {
      btn.addEventListener('click', function (e) {
        e.preventDefault();
        e.stopPropagation();

        const action = btn.dataset.action;
        if (action === 'select-all') {
          setAll(true);
        } else if (action === 'clear-all') {
          setAll(false);
        }
      });
    });

    document.addEventListener('click', function (e) {
      if (!wrapper.contains(e.target)) {
        wrapper.classList.remove('open');
      }
    });

    checkboxes.forEach(cb => {
      cb.addEventListener('change', () => {
        updateSummary();
        hideClientError();
      });
    });

    if (form) {
      form.addEventListener('submit', function (e) {
        const DEFAULT_VALUE = 'Не задано';

        const titleInput  = document.getElementById('id_title');
        const authorInput = document.getElementById('id_author');
        const deptInput   = document.getElementById('id_department');

        if (titleInput && !titleInput.value.trim()) {
          titleInput.value = DEFAULT_VALUE;
        }
        if (authorInput && !authorInput.value.trim()) {
          authorInput.value = DEFAULT_VALUE;
        }
        if (deptInput && !deptInput.value.trim()) {
          deptInput.value = DEFAULT_VALUE;
        }
        if (getChecked().length === 0) {
          e.preventDefault();
          showClientError();
          trigger.focus();
        }
      });
    }
  })();

  </script>
{% endblock content %}

Ізтөлеу З.Н. Закен Ж.Б. Сагитова Ш.Г.

Теңдеулер мен теңсіздіктер

СЕМЕЙ 2025 ЖЫЛ
АЛҒЫ СӨЗ
Құрметті оқырман! Сіздің алдыңызда математикалық анализдің іргетасы болып табылатын, кез келген дәл ғылым мен техниканың өзегін құрайтын – теңдеулер мен теңсіздіктер теориясына арналған еңбек тұр. Бұл екі ұғым математикалық модельдеудің негізгі құралдары болып саналады және олардың терең өзара байланысы бар.
Теңдеулер (equation) – айнымалылар арасындағы дәл теңдікті бейнелейді. Олар нақты заңдылықтарды, жүйенің тепе-теңдік жағдайын немесе екі шаманың бірдей мәнге ие болатын сәтін сипаттайды. Физикадағы іргелі заңдар (мысалы, Ньютонның екінші заңы), инженериядағы оптималды шешімдер, экономикадағы ұсыныс пен сұраныс теңестігі – осының бәрі теңдеулер арқылы өрнектеледі. Теңдеулер – дәлдіктің және нақтылықтың тілі.
Ал теңсіздіктер (inequality) – шамалар арасындағы салыстырмалы қатынасты («кем емес», «артық емес», «аралығында») анықтайды. Нақты өмірдегі процестердің басым бөлігі белгілі бір шектеулермен, қауіпсіздік нормаларымен, мүмкіндіктер аймағымен шектеледі. Мысалы, ресурстарды тиімді бөлу, қателіктердің рұқсат етілген шегі, өсу қарқынының максималды мәні – бұл шектеулілік пен мүмкіндіктерді сипаттайтын теңсіздіктердің пәні.
Бұл оқу құралы сізді қарапайым сызықтық өрнектерден бастап, күрделі квадраттық, рационал, көрсеткіштік, логарифмдік және тригонометриялық теңдеулер мен теңсіздіктерді шешудің әдістемелік негіздерімен қаруландырады. Біз тек алгоритмдік шешімдерді ғана емес, сонымен қатар математикалық пайымдау мен логикалық дәлелдеудің (proof) мәдениетін қалыптастыруға баса назар аударамыз. Сіз әрбір шешімнің неліктен дұрыс екенін түсіну арқылы, математикалық идеялардың шындығын өз бетіңізше дәлелдей алатын математикалық талдаудың іргетасын қалайсыз.
Бұл білім – сіздің логикалық ойлау және проблемаларды сын тұрғысынан шешу қабілетіңізді айтарлықтай жетілдіреді. Теңдеулер мен теңсіздіктерді меңгеру – кез келген ғылыми, инженерлік немесе экономикалық саладағы жетістігіңіздің кілті, өйткені ол дәлдікке, дәйектілікке және шектеулі жағдайларды дұрыс бағалай білуге үйретеді.
Ендеше, бізбен бірге математикалық тепе-теңдік пен салыстырмалылықтың терең әлеміне саяхат жасауға дайын болыңыз!
Сәттілік тілейміз!

